#nullable enable
using Alba;
using Microsoft.Extensions.DependencyInjection;
using Drafting.Contracts;
using Drafting.Slices.Drafting;
using Drafting.Views;
using Marten;
using Shouldly;
using Wolverine;
using Xunit;

namespace Drafting.IntegrationTests.Slices.Drafting;

/// <summary>
/// ONE SLICE, TWO IMPLEMENTATIONS, THE SAME FOUR RULES.
///
/// Both use Wolverine's aggregate handler workflow — <c>[WriteAggregate]</c> fetches the stream, folds it live
/// and carries its version into the append. The only difference is transport:
///
///   ReviseSubjectEndpoint   Wolverine.HTTP. Identity from the ROUTE. Refusal is ProblemDetails.
///   ReviseSubjectHandler    no HTTP at all. Identity named on the COMMAND. Refusal is an outcome object.
///
/// Every GWT below is asserted against both, through <see cref="Revise"/>, so a rule that holds for one and
/// not the other is a failure rather than a footnote. That is the point of the comparison: the model does not
/// choose the transport, so the transport must not change the behaviour.
///
/// The one asymmetry is real and is asserted rather than hidden — see <see cref="OnlyTheHttpPathRunsTheValidator"/>.
/// </summary>
public sealed class ReviseSubjectTests(AppFixture fixture) : IntegrationContext(fixture)
{
    public enum Via { Http, Message }

    private static readonly Guid Missing = Guid.Parse("dddddddd-dddd-dddd-dddd-dddddddddddd");

    /// <summary>GIVEN a draft exists. History, appended straight to the stream.</summary>
    private async Task<Guid> Drafted(string subject = "Original subject")
    {
        var emailId = Guid.NewGuid();
        await Given(emailId, new EmailDrafted(
            emailId, "someone@example.com", subject, "Body", SeedData.SeededAt));
        return emailId;
    }

    /// <summary>
    /// WHEN the command is issued — either way, normalised to (rule, succeeded) so one assertion covers both.
    /// Normalising the SHAPE of a refusal is exactly what the kit claims is possible: the rule name is the
    /// machine-readable part regardless of transport, and everything else about the two differs.
    /// </summary>
    private async Task<(bool Ok, string? Rule)> Revise(Via via, Guid emailId, string subject)
    {
        if (via == Via.Message)
        {
            using var scope = Host.Services.CreateScope();
            var outcome = await scope.ServiceProvider.GetRequiredService<IMessageBus>()
                .InvokeAsync<ReviseOutcome>(new ReviseSubject(emailId, subject));
            return (outcome.WasRevised, outcome.Rule);
        }

        var (_, result) = await WhenPosting(x =>
        {
            x.Post.Json(new ReviseSubject(emailId, subject)).ToUrl($"/emails/{emailId}/subject");
            x.IgnoreStatusCode();
        });

        if (result.Context.Response.StatusCode == 204) return (true, null);

        var problem = await result.ReadAsJsonAsync<Microsoft.AspNetCore.Mvc.ProblemDetails>();
        return (false, problem?.Title);
    }

    // a draft's subject can be revised
    //   GIVEN EmailDrafted
    //   WHEN  ReviseSubject
    //   THEN  SubjectRevised
    [Theory]
    [InlineData(Via.Http)]
    [InlineData(Via.Message)]
    public async Task ADraftsSubjectCanBeRevised(Via via)
    {
        var emailId = await Drafted();

        var (ok, rule) = await Revise(via, emailId, "A better subject");

        ok.ShouldBeTrue();
        rule.ShouldBeNull();

        var revised = (await EventsFor(emailId)).OfType<SubjectRevised>().ShouldHaveSingleItem();
        revised.Subject.ShouldBe("A better subject");

        // The read model followed, in the same transaction as the append.
        await using var session = Store.QuerySession();
        (await session.LoadAsync<MyDrafts>(emailId))!.Subject.ShouldBe("A better subject");
    }

    // revising to the subject it already has changes nothing
    //   GIVEN EmailDrafted
    //   WHEN  ReviseSubject
    //   THEN  error: NothingChanged
    [Theory]
    [InlineData(Via.Http)]
    [InlineData(Via.Message)]
    public async Task RevisingToTheSubjectItAlreadyHasChangesNothing(Via via)
    {
        var emailId = await Drafted("Original subject");

        // THE RULE THAT NEEDS THE FOLD. Nothing in the request reveals it — you have to know what the subject
        // already is, and only the accumulated stream knows that. This is what [WriteAggregate] hands over,
        // and the reason this slice is worth having as a reference at all.
        var (ok, rule) = await Revise(via, emailId, "Original subject");

        ok.ShouldBeFalse();
        rule.ShouldBe("NothingChanged");

        (await EventsFor(emailId)).OfType<SubjectRevised>().ShouldBeEmpty();
    }

    // a draft nobody wrote cannot be revised
    //   GIVEN (nothing)
    //   WHEN  ReviseSubject
    //   THEN  error: NotDrafted
    [Theory]
    [InlineData(Via.Http)]
    [InlineData(Via.Message)]
    public async Task ADraftNobodyWroteCannotBeRevised(Via via)
    {
        // No GIVEN. An absent stream folds to a default instance, so "nobody drafted this" and "this email
        // does not exist" are the same state.
        //
        // Both implementations pass Required = false to get here at all. Left required, the HTTP endpoint
        // would answer a framework 404 carrying no rule name — and the MESSAGE handler would log and DISCARD
        // the message, making this rule unobservable: nothing fails, nothing returns, the rule quietly does
        // not exist. That asymmetry is the sharpest difference between the two transports.
        var (ok, rule) = await Revise(via, Missing, "Anything");

        ok.ShouldBeFalse();
        rule.ShouldBe("NotDrafted");
    }

    // a blank subject is refused
    //   GIVEN (nothing)
    //   WHEN  ReviseSubject
    //   THEN  error: SubjectRequired
    [Fact]
    public async Task ABlankSubjectIsRefused()
    {
        var emailId = await Drafted();

        var (_, result) = await WhenPosting(x =>
        {
            x.Post.Json(new ReviseSubject(emailId, "")).ToUrl($"/emails/{emailId}/subject");
            x.IgnoreStatusCode();
        });

        result.Context.Response.StatusCode.ShouldBe(400);

        // THE RULE NAME IS IN errors, NOT IN Title. FluentValidation's middleware sets Title to the generic
        // "One or more validation errors occurred." and puts the per-field messages underneath. A decider's
        // refusal puts the rule name in Title. So the two enforcement points do NOT share a response shape —
        // only the guarantee that the rule name is somewhere machine-readable in the body.
        (await result.ReadAsTextAsync()).ShouldContain("SubjectRequired");

        (await EventsFor(emailId)).OfType<SubjectRevised>().ShouldBeEmpty();
    }

    /// <summary>
    /// THE PERIPHERY RULE HOLDS ON BOTH PATHS — AND FAILS DIFFERENTLY. This test exists because I expected the
    /// opposite and was wrong, which makes it worth pinning.
    ///
    /// The guess was that <c>UseFluentValidation()</c> only wires Wolverine.HTTP's middleware, so a caller
    /// invoking the message handler directly would slip past SubjectRequired and reach the decider. It does
    /// not: Wolverine applies validation to MESSAGE handlers as well, and the blank subject is refused on
    /// both paths. Good news for the kit — <c>enforce="periphery"</c> is a property of the slice, not of a
    /// transport, so choosing the non-HTTP shape does not quietly drop a rule.
    ///
    /// What genuinely differs is the SHAPE of the failure, and it is a sharp difference:
    ///
    ///   HTTP     400 with ProblemDetails; the rule name is in errors, and Title is generic
    ///   message  a thrown FluentValidation.ValidationException — an exception, not a return value
    ///
    /// So a caller of the message path cannot treat a rule violation the way it treats NotDrafted or
    /// NothingChanged. Those come back as an outcome; this one is thrown. Anything issuing this command in
    /// process has to catch, and nothing about the model says so.
    /// </summary>
    [Fact]
    public async Task ThePeripheryRuleHoldsOnBothPathsButFailsDifferently()
    {
        var emailId = await Drafted();

        var blankViaMessage = async () =>
        {
            using var scope = Host.Services.CreateScope();
            await scope.ServiceProvider.GetRequiredService<IMessageBus>()
                .InvokeAsync<ReviseOutcome>(new ReviseSubject(emailId, ""));
        };

        var thrown = await blankViaMessage.ShouldThrowAsync<FluentValidation.ValidationException>();
        thrown.Message.ShouldContain("ReviseSubject");

        // Refused, so nothing was appended — same outcome as HTTP, reached by a different road.
        (await EventsFor(emailId)).OfType<SubjectRevised>().ShouldBeEmpty();
    }
}
